-- 由 tools/add_songs.py 生成，音频复用已合成的 8 段示例音频。
USE music_db;

ON DUPLICATE KEY UPDATE name = VALUES(name), avatar = VALUES(avatar), cover = VALUES(cover),
  gender = VALUES(gender), region = VALUES(region), birthday = VALUES(birthday), intro = VALUES(intro);

ON DUPLICATE KEY UPDATE name = VALUES(name), singer_id = VALUES(singer_id),
  cover = VALUES(cover), publish_date = VALUES(publish_date), company = VALUES(company), intro = VALUES(intro);

ON DUPLICATE KEY UPDATE name = VALUES(name), singer_id = VALUES(singer_id), album_id = VALUES(album_id),
  cover = VALUES(cover), audio_url = VALUES(audio_url), lyric = VALUES(lyric),
  duration = VALUES(duration), category_id = VALUES(category_id), play_count = VALUES(play_count),
  like_count = VALUES(like_count), is_recommend = VALUES(is_recommend);


SELECT COUNT(*) AS song_total FROM song;