INSERT INTO singer (id, name, avatar, cover, gender, region, birthday, intro, follow_count) VALUES
(9, '周杰伦', '/images/singer/s9.png', '/images/singer/cover/s9.png', 1, '华语', '1979-01-18', '华语流行天王，把中国风、说唱与钢琴旋律写进大众记忆。', 2433),
(10, '林俊杰', '/images/singer/s10.png', '/images/singer/cover/s10.png', 1, '新加坡', '1981-03-27', '新加坡创作型歌手，以细腻转音与钢琴情歌著称。', 2570),
(11, '邓紫棋', '/images/singer/s11.png', '/images/singer/cover/s11.png', 2, '中国香港', '1991-08-16', '90 后唱作人，高音扎实，流行与电子元素融合。', 2707),
(12, '陈奕迅', '/images/singer/s12.png', '/images/singer/cover/s12.png', 1, '中国香港', '1974-07-27', '香港乐坛常青树，用叙事感极强的嗓音唱都市心事。', 2844),
(13, '毛不易', '/images/singer/s13.png', '/images/singer/cover/s13.png', 1, '中国内地', '1994-10-11', '民谣唱作人，词句平实，写尽普通人的日常。', 2981),
(14, '薛之谦', '/images/singer/s14.png', '/images/singer/cover/s14.png', 1, '中国内地', '1983-07-17', '华语流行男歌手，擅长副歌极具记忆点的情歌。', 3118),
(15, '告五人', '/images/singer/s15.png', '/images/singer/cover/s15.png', 0, '中国台湾', '2017-01-01', '双主唱独立乐团，旋律明亮，编曲带着公路感。', 3255),
(16, '张韶涵', '/images/singer/s16.png', '/images/singer/cover/s16.png', 2, '中国台湾', '1982-01-19', '华语流行女歌手，声音清亮，代表作传唱度极高。', 3392)
INSERT INTO album (id, name, singer_id, cover, publish_date, company, intro) VALUES
(11, '叶惠美', 9, '/images/album/a11.png', '2003-07-31', '杰威尔音乐', '周杰伦的第四张录音室专辑，中国风与校园叙事的代表作。'),
(12, '第二天堂', 10, '/images/album/a12.png', '2004-06-04', '海蝶音乐', '林俊杰早期代表作专辑，钢琴与转音的结合。'),
(13, 'Xposed', 11, '/images/album/a13.png', '2012-08-01', '蜂鸟音乐', '邓紫棋的转型专辑，唱腔与编曲都更具张力。'),
(14, '认了吧', 12, '/images/album/a14.png', '2007-04-24', '环球唱片', '陈奕迅国语专辑，城市情歌的叙事范本。'),
(15, '平凡的一天', 13, '/images/album/a15.png', '2018-05-31', '哇唧唧哇', '毛不易首张个人专辑，写给普通人的日常。'),
(16, '绅士', 14, '/images/album/a16.png', '2015-06-08', '海蝶音乐', '薛之谦的流行情歌专辑，副歌记忆点极强。'),
(17, '运气来得若有似无', 15, '/images/album/a17.png', '2021-09-03', '相信音乐', '告五人专辑，旋律明亮，带着公路与海风的味道。'),
(18, '潘朵拉', 16, '/images/album/a18.png', '2006-01-06', '福茂唱片', '张韶涵的代表专辑，清亮嗓音与励志旋律。')
INSERT INTO song (id, name, singer_id, album_id, cover, audio_url, lyric, duration, category_id, play_count, like_count, comment_count, is_recommend, status, create_time) VALUES
(17, '晴天', 9, 11, '/images/album/a11.png', '/audio/track-1.wav', '[00:00.00]晴天 - 周杰伦\n[00:02.00]作词：演示数据　作曲：演示数据\n[00:04.00]风把心事吹成了雨\n[00:09.00]沿着旧街走到清晨\n[00:14.00]我想再看一次海\n[00:20.00]路灯下的影子很长\n[00:25.00]在每一个失眠的夜里\n[00:30.00]城市的灯 一盏盏亮起\n[00:36.00]还在耳机里轻轻回旋\n[00:41.00]如果时间可以倒带', 48, 1, 1286000, 4946, 0, 1, 1, '2003-07-31 10:00:00'),
